#include "sys_clk.h"
#include "FreeRTOS.h"

void main()

{
APP_Start();
}

static void APP_Start()
{

	xTaskCreate(application_read_task_entry,
				"DataTask",
				1024,
				(void *)0,
				tskIDLE_PRIORITY + 4,
				NULL );

	xTaskCreate(application_process_task_entry,
				"ProcessTask",
				1024,
				(void *)0,
				tskIDLE_PRIORITY + 3,
				NULL );


	xTaskCreate(application_LCD_DISPLAY_task_entry,
				"PrintTask",
				1024,
				(void *)0,
				tskIDLE_PRIORITY + 2,
				NULL );

}
